import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * TASK: Describe a class's instance fields.
 *
 * fieldTypes(c) returns a Map from each INSTANCE field's name to its type's
 * simple name, in declared order. Use a LinkedHashMap so the order survives.
 *
 *   c.getDeclaredFields()           -- every field declared by c, any access level
 *   Modifier.isStatic(f.getModifiers()) -- true for a static field: SKIP those
 *   f.isSynthetic()                 -- compiler-generated: skip those too
 *   f.getType().getSimpleName()     -- "String", "double", "int[]", "List"
 *
 * Note that getSimpleName drops the package, so java.util.List becomes just
 * "List", and an array type keeps its brackets: int[].
 *
 * Example, for WeatherSensor:
 *   fieldTypes(WeatherSensor.class).get("reading") -> "double"
 *   fieldTypes(WeatherSensor.class).get("history") -> "int[]"
 *   fieldTypes(WeatherSensor.class).size()         -> 4
 * The static field "created" is not in the map.
 */
// Provided -- do not edit.
class WeatherSensor {

    private String id;
    private double reading;
    private int[] history;
    private java.util.List<String> tags;
    private static int created;

    WeatherSensor(String id) {
        this.id = id;
        this.reading = 0.0;
        this.history = new int[0];
        this.tags = new java.util.ArrayList<>();
        created++;
    }
}

// Provided -- do not edit.
class BlankSensor {
}

public class FieldTypeMapper {

    public static Map<String, String> fieldTypes(Class<?> c) {
        Map<String, String> types = new LinkedHashMap<>();
        // TODO: add one entry per non-static, non-synthetic declared field
        return types;
    }
}

