public class FieldTypeMapperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            java.util.Map<String, String> types = FieldTypeMapper.fieldTypes(WeatherSensor.class);

            check("only the instance fields are counted", 4, types == null ? null : types.size());
            check("a String field", "String", types == null ? null : types.get("id"));
            check("a primitive field", "double", types == null ? null : types.get("reading"));
            check("an array field keeps its brackets", "int[]",
                    types == null ? null : types.get("history"));
            check("getSimpleName drops the package", "List",
                    types == null ? null : types.get("tags"));
            check("the static field is skipped", null, types == null ? "map was null" : types.get("created"));
            check("declared order is preserved", "[id, reading, history, tags]",
                    types == null ? null : types.keySet().toString());
            check("a class with no fields", 0,
                    FieldTypeMapper.fieldTypes(BlankSensor.class) == null ? null
                            : FieldTypeMapper.fieldTypes(BlankSensor.class).size());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

